        vm.prank(owner);
        c.XBornID();
        // Assert the reference contract sets balances[owner] to totalDistributed (200000000e18)
        // The buggy version has empty body, so balances[owner] remains 0
        assertTrue(c.balanceOf(owner) == 200000000e18);
    }
}

