// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy: owner is the test contract (address(this)).
        // First, get owner's initial balance (should be 0 before any distribution).
        uint256 initialOwnerBalance = c.balanceOf(address(this));
        // Let a different account (non-owner) try to call XBornID()
        address attacker = address(0xdead);
        vm.prank(attacker);
        // Try-catch to see if it reverts (correct) or succeeds (bug)
        bool succ;
        try c.XBornID() {
            succ = true;
        } catch {
            succ = false;
        }
        // The correct contract should revert (succ == false) because onlyOwner modifier is present.
        // The buggy version removes the modifier, so it would succeed and overwrite balances[owner].
        // Assert: in correct version, owner's balance unchanged (still initialOwnerBalance) because call reverted.
        // In buggy version, owner's balance becomes totalDistributed (200000000e18) and succ == true.
        // We check: if succ is false, then the balance stayed the same; if succ is true, we can also detect via balance but the key is revert.
        // However the assertion must break on bug: we want a property that reference satisfies AND bug breaks.
        // Reference: after the call, owner's balance == initialOwnerBalance (0) because call reverted.
        // Bug: owner's balance becomes totalDistributed (200000000e18) -> not equal to initialOwnerBalance.
        assertTrue(c.balanceOf(address(this)) == initialOwnerBalance);
    }
}

