pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // First, getTokens() to increase totalDistributed
        // We need to send ether to trigger getTokens() via receive()
        // But the contract requires value <= totalRemaining (300000000e18)
        // and blacklist[msg.sender] == false
        // value is initially 1000e18, so sending 1 wei will trigger getTokens()
        vm.deal(address(this), 1 ether);
        vm.prank(address(this));
        (bool success, ) = address(c).call{value: 1 wei}("");
        require(success, "call failed");
        // Now totalDistributed = 200000000e18 + 1000e18 = 200001000e18
        // totalRemaining = 300000000e18 - 1000e18 = 299999000e18
        // Now call XBornID() as owner
        vm.prank(c.owner());
        c.XBornID();
        // In reference: totalDistributed increased by _amount (0) => stays 200001000e18
        // balances[owner] = totalDistributed = 200001000e18
        // In bug: totalDistributed decreases by _amount (0) => stays 200001000e18
        // Actually both have same balances because _amount=0. Let's use a different approach.
        // Instead, call getTokens twice: first time adds 1000e18, second time adds 99999/100000 * 1000e18 = 999.99e18 approx
        // But we need a concrete difference. Better: call burn first to reduce totalDistributed, then XBornID() sets balances[owner] incorrectly.
        // Reset: deploy fresh
        c = new C();
        // Call burn to reduce totalDistributed from 200000000e18 to 100000000e18
        // But burn requires _value <= balances[msg.sender] and owner is msg.sender
        // balances[owner] initially 0, so cannot burn. Let's fund owner first.
        // Actually XBornID() must be called first to give owner balance.
        // So sequence: call XBornID() first sets balances[owner] = totalDistributed = 200000000e18
        // Then burn 100000000e18 to reduce totalDistributed to 100000000e18
        // Then call XBornID() again? But it's not a function that can be called again.
        // Let's just use the original plan: call getTokens() once, then XBornID(), then check balances[owner] equals totalDistributed.
        // In reference: totalDistributed = 200001000e18, balances[owner] = 200001000e18
        // In bug: totalDistributed = 200001000e18 - 0 = 200001000e18, same. Not diverging.
        // We need the bug to subtract a non-zero _amount from totalDistributed.
        // But distr is private; the only public calls that set _amount are getTokens() which uses value (non-zero).
        // After getTokens(), distr adds value to totalDistributed. In bug, subtracts value.
        // So totalDistributed becomes 200000000e18 - 1000e18 = 199999000e18.
        // Then XBornID() sets balances[owner] = totalDistributed = 199999000e18.
        // In reference, after getTokens(), totalDistributed = 200001000e18, XBornID() sets balances[owner] = 200001000e18.
        // So final check: balances[owner] should be 200001000e18 in reference, but bug has 199999000e18.
        // Simple assertion: c.balanceOf(c.owner()) == 200001000e18 in reference, fails in bug.
        assertTrue(c.balanceOf(c.owner()) == 200001000e18, "balances[owner] mismatch");
    }
}

