import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: deploy, get owner address
        address owner = address(this);
        address user = address(0x1234);

        // Give user some ETH to call getTokens
        vm.deal(user, 1 ether);

        // Call XBornID to initialize balances[owner] = totalDistributed = 200M
        c.XBornID();

        // Now call getTokens as user – in reference, totalRemaining = 300M, value = 1000e18, so it succeeds
        vm.prank(user);
        c.getTokens{value: 0}();

        // In reference, totalRemaining becomes 300M - 1000e18 = 299999000000000000000000000 (still > 0)
        // In buggy, totalRemaining becomes 500M + 1000e18 = 500001000000000000000000000 (still > 0)
        // Both succeed

        // Now transfer some ETH to contract so it has balance
        vm.deal(owner, 1 ether);
        vm.prank(owner);
        payable(address(c)).transfer(0.5 ether);

        // In reference, totalDistributed == 200001000e18 < totalSupply (500M), so distributionFinished is false
        // But after getTokens, blacklist[user] = true, so user cannot call again
        // The contract has 0.5 ETH

        // Owner calls withdraw
        uint256 beforeBalance = address(owner).balance;
        c.withdraw();
        uint256 afterBalance = address(owner).balance;

        // Reference: withdraw succeeded, owner got 0.5 ETH
        // Buggy: same behavior for this simple case
        // The divergence is actually in totalRemaining value after distr

        // Better test: check totalRemaining via the public getter
        // Reference: totalRemaining = 300000000000000000000000000 - 1000e18 = 299999000000000000000000000
        // Buggy: totalRemaining = 500000000000000000000000000 + 1000e18 = 500001000000000000000000000
        uint256 expectedRef = 300000000000000000000000000 - 1000e18;
        assertTrue(c.totalRemaining() == expectedRef);
    }
}

